## Bug report

**Required Info:**

- Operating System:
  - Ubuntu 22.04
- Installation type:
  - Humble Binaries with package tf2_ros rebuilt from source just to add more logs as below (humble branch: tag: 0.25.8)
- Version or commit hash:
  - tag: 0.25.8
- DDS implementation:
  - default used by ros2 humble

#### Setup

This has been tested on ROS2 Humble. To better see/reproduce the issue, I created a project example:
[tf2_buffer_lag_v3.zip](https://github.com/user-attachments/files/17709775/tf2_buffer_lag_v3.zip). Unzip the attached code project (called `tf2_buffer_lag`) in your workspace.

We also have to rebuild [tf2_ros](https://github.com/ros2/geometry2/tree/humble/tf2_ros) package (humble branch) in the workspace to add the following debug logs to `transform_listener.cpp` at the end of the `subscription_callback` function, here is the patch (this shows how many times the callback has been called during the last second, and also show maximum interval):
```diff
diff --git a/tf2_ros/src/transform_listener.cpp b/tf2_ros/src/transform_listener.cpp
index 3f59d5f0..34713edc 100644
--- a/tf2_ros/src/transform_listener.cpp
+++ b/tf2_ros/src/transform_listener.cpp
@@ -87,6 +87,29 @@ void TransformListener::subscription_callback(
         msg_in.transforms[i].header.frame_id.c_str(), temp.c_str());
     }
   }
+
+  static double lastCall = rclcpp::Clock().now().seconds();
+  static int count = 0;
+  static double largestInterval = 0.0;
+  ++count;
+  double interval = rclcpp::Clock().now().seconds() - lastCall;
+  if(interval > largestInterval)
+  {
+    largestInterval = interval;
+  }
+  lastCall = rclcpp::Clock().now().seconds();
+  static double lastTime = rclcpp::Clock().now().seconds();
+  if(lastCall - lastTime > 1)
+  {
+    RCLCPP_WARN(
+        node_logging_interface_->get_logger(),
+        "Received %d frames in the past %.3f seconds (max interval=%.3f)",
+        count, lastCall - lastTime, largestInterval);
+
+    lastTime = lastCall;
+    count = 0;
+    largestInterval = 0.0;
+  }
 }
 
 }  // namespace tf2_ros
```




#### Steps to reproduce issue

Open 5 terminals:

1. Start the camera node: it publishes a 1920x1080 dummy image at 30 Hz

```
ros2 run tf2_buffer_lag camera_node
```
<details><summary>(click to see relevant code)</summary>

```cpp
#include "rclcpp/rclcpp.hpp"
#include <sensor_msgs/msg/image.hpp>

class CameraNode : public rclcpp::Node
{
public:
	explicit CameraNode(const rclcpp::NodeOptions & options) :
		CameraNode("camera", options)
	{}
	explicit CameraNode(const std::string & name, const rclcpp::NodeOptions & options) :
		Node(name, options),
		thread_running_(true)
	{
		pub_ = create_publisher<sensor_msgs::msg::Image>("/camera/image_raw", rclcpp::QoS(1));
		transform_thread_.reset(new std::thread([&]()
		{
			rclcpp::Rate r(30);
			while(thread_running_)
			{
				sensor_msgs::msg::Image msg;
				msg.header.frame_id = "camera_optical_frame";
				msg.header.stamp = now();
				msg.width = 1920;
				msg.height = 1080;
				msg.data.resize(msg.height * msg.width);
				pub_->publish(msg);
				r.sleep();
			}
		}));
	}
	virtual ~CameraNode() {
		thread_running_ = false;
		transform_thread_->join();
	}

private:
	rclcpp::Publisher<sensor_msgs::msg::Image>::SharedPtr pub_;
	std::shared_ptr<std::thread> transform_thread_;
	bool thread_running_;
};

int main(int argc, char** argv)
{
	rclcpp::init(argc, argv);
	rclcpp::spin(std::make_shared<CameraNode>(rclcpp::NodeOptions()));
	rclcpp::shutdown();
	return 0;
}
```
</details>

2. Start the tf broadcaster: it publishes a tf between `odom` and `base_link` at 30 Hz and 50 ms delay (simulating visual odometry)

```
ros2 run tf2_buffer_lag broadcaster_node
```
<details><summary>(click to see relevant code)</summary>

```cpp
#include "rclcpp/rclcpp.hpp"
#include <tf2_ros/transform_broadcaster.h>

class BroadcasterNode : public rclcpp::Node
{
public:
	explicit BroadcasterNode(const rclcpp::NodeOptions & options) :
		BroadcasterNode("broadcaster", options)
	{}
	explicit BroadcasterNode(const std::string & name, const rclcpp::NodeOptions & options) :
		Node(name, options),
		thread_running_(true)
	{
		tf_broadcaster_ = std::make_shared<tf2_ros::TransformBroadcaster>(this);
		transform_thread_.reset(new std::thread([&]()
		{
			rclcpp::Rate r(30);
			while(thread_running_)
			{
				geometry_msgs::msg::TransformStamped msg;
				msg.child_frame_id = "base_link";
				msg.header.frame_id = "odom";
				msg.header.stamp = now() - rclcpp::Duration::from_seconds(0.05); // add 50 ms delay
				msg.transform.rotation.w = 1.0;
				tf_broadcaster_->sendTransform(msg);
				r.sleep();
			}
		}));
	}
	virtual ~BroadcasterNode() {
		thread_running_ = false;
		transform_thread_->join();
	}

private:
	std::shared_ptr<tf2_ros::TransformBroadcaster> tf_broadcaster_;
	std::shared_ptr<std::thread> transform_thread_;
	bool thread_running_;
};

int main(int argc, char** argv)
{
	rclcpp::init(argc, argv);
	rclcpp::spin(std::make_shared<BroadcasterNode>(rclcpp::NodeOptions()));
	rclcpp::shutdown();
	return 0;
}
```
</details>

3. Start our baseline TF listener node calling `tf2::Buffer::lookupTransform` with a timer at 50 Hz and with a timeout of 500 ms

```
ros2 run tf2_buffer_lag listener_node
```

<details><summary>(click to see relevant code)</summary>

```cpp

#include "rclcpp/rclcpp.hpp"
#include <tf2_ros/buffer.h>
#include <tf2_ros/transform_listener.h>
#include <sensor_msgs/msg/image.hpp>
#include <functional>

class ListenerNode : public rclcpp::Node
{
public:
	explicit ListenerNode(const rclcpp::NodeOptions & options) :
		ListenerNode("listener", options)
	{}
	explicit ListenerNode(const std::string & name, const rclcpp::NodeOptions & options) :
		Node(name, options)
	{
		bool sub_topic = false;
		sub_topic = this->declare_parameter("sub_topic", sub_topic);

		tf_buffer_ = std::make_shared<tf2_ros::Buffer>(this->get_clock());
		tf_listener_ = std::make_shared<tf2_ros::TransformListener>(*tf_buffer_);

		if(sub_topic) {
			RCLCPP_INFO(get_logger(), "Subscribing to topic");
			sub_ = create_subscription<sensor_msgs::msg::Image>("/camera/image_raw", rclcpp::QoS(1), std::bind(&ListenerNode::callbackTopic, this, std::placeholders::_1));
		}
		else {
			RCLCPP_INFO(get_logger(), "Starting timer loop");
			lookup_timer_ = this->create_wall_timer(std::chrono::milliseconds(20), std::bind(&ListenerNode::callbackTimer, this));  
		}
	}

	void callbackTimer()
	{
		try
		{
			geometry_msgs::msg::TransformStamped tmp;
			tmp = tf_buffer_->lookupTransform("odom", "base_link", now(), rclcpp::Duration::from_seconds(0.5));
		}
		catch(tf2::TransformException & ex)
		{
			RCLCPP_ERROR(get_logger(), "%s (timeout=%.3fs)", ex.what(), 0.5);
		}
	}

	void callbackTopic(
		const sensor_msgs::msg::Image::ConstSharedPtr image)
	{
		try
		{
			geometry_msgs::msg::TransformStamped tmp;
			tmp = tf_buffer_->lookupTransform("odom", "base_link", image->header.stamp, rclcpp::Duration::from_seconds(0.5));
		}
		catch(tf2::TransformException & ex)
		{
			RCLCPP_ERROR(get_logger(), "%s (timeout=%.3fs)", ex.what(), 0.5);
		}
	}
	virtual ~ListenerNode() {

	}

private:
	std::shared_ptr<tf2_ros::Buffer> tf_buffer_;
	std::shared_ptr<tf2_ros::TransformListener> tf_listener_;
	rclcpp::TimerBase::SharedPtr lookup_timer_;
	rclcpp::Subscription<sensor_msgs::msg::Image>::SharedPtr sub_;
};

int main(int argc, char** argv)
{
	rclcpp::init(argc, argv);
	rclcpp::spin(std::make_shared<ListenerNode>(rclcpp::NodeOptions()));
	rclcpp::shutdown();
	return 0;
}
```
</details>

4. Start the problematic image subscriber calling `tf2::Buffer::lookupTransform` at image rate with a timeout of 500 ms
```
ros2 run tf2_buffer_lag listener_node --ros-args -p sub_topic:=true
```

On terminals 3 and 4 (if you added the patch to tflistener), you should see this log every second:
```
[WARN] [1731370012.290011471] [transform_listener_impl_567178f2ca30]: Received 30 frames in the past 1.000 seconds (max interval=0.034)
[WARN] [1731370013.323346412] [transform_listener_impl_567178f2ca30]: Received 31 frames in the past 1.033 seconds (max interval=0.034)
[WARN] [1731370014.356675864] [transform_listener_impl_567178f2ca30]: Received 31 frames in the past 1.033 seconds (max interval=0.034)
```

At this point, there should not be any error (everything is working as expected). 

5. In Terminal 5, start [stress](https://manpages.ubuntu.com/manpages/jammy/man1/stress.1.html) tool with the number of cpus on your computer. For example, I have 16 cores on my computer, I would do:
```
stress -c 16
```

The CPU usage of your machine would be now at 100%. In terminal 3, there should still be the normal log as above indicating that the node is still receiving TF and is able to wait for it without delay. In terminal 4, you should start to see errors like this:
